// TRANSITIONS gains a zone dimension
'death-retry': { run: 'rollback', life: 'reset', zone: 'rebuild' },
'continue':    { run: 'refill-lives', life: 'reset', zone: 'rebuild' },
'save-load':   { run: 'restore',    life: 'reset', zone: 'rebuild' },
// advance/new-game: zone: 'keep' (caller already installed fresh content)

export function enterZone(h, zone, transition, ctx) {
  const rule = TRANSITIONS[transition];
  applyRunRule(rule, h);        // existing wallet/lives rollback
  applyLifeRule(rule, h);       // existing transient resets
  if (rule.zone === 'rebuild') rebuildZoneContent(ctx); // moved from resetActiveZoneContent
  placeHeroAtEntry(h);          // pinned order - never reorder
  resetHitstop();
  showAreaEntry(h, ctx);
}

// same hero + run survive, zone content is swapped
const heroBefore = h;
enterZone(h, zone, 'death-retry', ctx);
assert.equal(heroBefore, h, 'hero instance survives');
assert.notEqual(enemiesBefore[0], ctx.enemies[0], 'enemies rebuilt fresh');
assert.equal(h.lives, livesBefore - 1); // per-rule, not per-object

